from research_helpers import *
rows=json.loads((out/'jersey-product-details.json').read_text())
ownership=ev('https://www.jec.co.uk/media/fn4pvjm2/annual-report-and-accounts-2024-web.pdf','Issuer identifies Powerhouse and powerhouse.je as its retail business. Listed brands are third-party products; link Jersey Electricity as commercial partner, never manufacturer.')
cats={'powerbanks':'https://www.powerhouse.je/smart-tech-phones-c952/phones-c151/powerbanks-c1024','portable':'https://www.powerhouse.je/smart-tech-phones-c952/powerstations-solar-c1334/portable-powerstations-and-solar-c1335','robots':'https://www.powerhouse.je/small-appliances-c958/floor-care-c501/robot-vacuums-c758'}
products=[]
for r in rows:
 robot=r['category']=='robots';source=ev(cats[r['category']],f"Current public retailer category lists {r['name']} under code {r['code']}. Catalogue code is retailer reference; manufacturer part-number equivalence not assumed. No real-time stock claim.")
 evidence=[source,ownership]
 if 'detail_text' in r:evidence.insert(0,ev(r['url'],'Individual product description read; battery capacity/chemistry only as explicitly stated. Retail catalogue listing does not establish product manufacture or guarantee stock.'))
 attrs={'brand':r['name'].split()[0],'retailer_catalogue_code':r['code'],'retailer':'Powerhouse','individual_page_retrieved':'detail_text' in r,'catalogue_product_name':r['name']}
 if r['code']=='379162':attrs['variant_scope']='DELTA 3 Series as listed; exact Plus/Classic variant unverified. Base capacity described as1kWh; expandable5kWh is system maximum, not included pack.'
 products.append(p(r['name'],'Third-party '+('robot vacuum/mop' if robot else 'portable battery/powerbank')+' listed by Jersey Electricity retail business Powerhouse. '+('Exact additional technical details unverified.' if 'error' in r else 'Individual retailer description verified; no manufacturer ownership attributed.'),source,'commercial',roles=['commercial_partner'],typ='product',sector='robotics' if robot else 'energy_storage',sub='service_robotics' if robot else 'batteries',attributes=attrs,evidence=evidence,territory='Jersey, Channel Islands'))
c=company('Jersey Electricity plc',products,[ownership]+[ev(u,'Current public category checked and model names/codes manually reviewed.') for u in cats.values()],'27 distinct battery/powerbank/station and robot-vacuum listings across three checked categories. Standalone EcoFlow solar panel excluded as generation-only. Powerhouse parent retail relationship only; no manufacturing/IP claim. Individual descriptions retrieved for a subset; remaining detail requests stopped on HTTP429. Catalogue identities supported by category listings. Exact variants and remaining rechargeable/replacement batteries or additional robotics categories still require review; utility battery projects/advice are not product SKUs.')
(out/'batch-0133.json').write_text(json.dumps({'companies':[c]},indent=2));print(len(products))
